import json, subprocess, time
previous = {'run_id': 'job-7391', 'status': 'running', 'result': None}
deadline = time.monotonic() + 2400
interval = 10
while time.monotonic() < deadline:
    time.sleep(interval)
    p = subprocess.run(['python3', 'bench_ci.py', 'status'], capture_output=True, text=True)
    if p.returncode:
        print(p.stdout + p.stderr, flush=True)
        raise SystemExit(p.returncode)
    status = json.loads(p.stdout)
    if status != previous:
        print(p.stdout.strip(), flush=True)
        previous = status
    if status.get('run_id') != 'job-7391':
        raise SystemExit('Unexpected run identity')
    if status.get('status') not in ('pending', 'queued', 'running', 'in_progress'):
        break
    interval = min(30, interval + 5)
else:
    print('Observation time limit reached', flush=True)
